  `payment_config_enc` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`payment_config_enc`)),
  `timezone` varchar(60) NOT NULL DEFAULT 'Asia/Dhaka',
